ON CONFLICT(id) DO UPDATE SET name=CASE WHEN length(excluded.name) >= length(importyeti_web_entities.name) THEN excluded.name ELSE importyeti_web_entities.name END,address=CASE WHEN importyeti_web_entities.address IS NULL OR NOT importyeti_web_entities.address GLOB '*[0-9]*' THEN excluded.address ELSE importyeti_web_entities.address END,country=excluded.country,website=COALESCE(excluded.website,importyeti_web_entities.website),total_shipments=CASE WHEN importyeti_web_entities.total_shipments IS NULL OR excluded.total_shipments > importyeti_web_entities.total_shipments THEN excluded.total_shipments ELSE importyeti_web_entities.total_shipments END,latest_shipment_date=COALESCE(excluded.latest_shipment_date,importyeti_web_entities.latest_shipment_date),avg_teu_per_shipment=COALESCE(excluded.avg_teu_per_shipment,importyeti_web_entities.avg_teu_per_shipment),avg_teu_per_month=COALESCE(excluded.avg_teu_per_month,importyeti_web_entities.avg_teu_per_month),estimated_shipping_spend_usd=COALESCE(excluded.estimated_shipping_spend_usd,importyeti_web_entities.estimated_shipping_spend_usd),shipping_spend_coverage_percent=COALESCE(excluded.shipping_spend_coverage_percent,importyeti_web_entities.shipping_spend_coverage_percent),contact_data_status=CASE WHEN importyeti_web_entities.contact_data_status IS NULL OR importyeti_web_entities.contact_data_status='not_checked' THEN excluded.contact_data_status ELSE importyeti_web_entities.contact_data_status END,source_url=excluded.source_url,search_query=excluded.search_query,captured_at=excluded.captured_at,raw_evidence=excluded.raw_evidence;

ON CONFLICT(id) DO UPDATE SET shipment_count=excluded.shipment_count,period_start=excluded.period_start,period_end=excluded.period_end,hs_codes=excluded.hs_codes,product_descriptions=excluded.product_descriptions,source_url=excluded.source_url,captured_at=excluded.captured_at;
